def get_product_list():
    return list(PRODUCTS.keys())

def get_product_detail(pid: str):
    import random
    product = PRODUCTS.get(pid)
    if product is None:
        raise ValueError(f"Product {pid} has been discontinued")
    return product

def get_product_reviews(pid: str):
    import random
    if random.random() < 0.3:
        return []  # Simulate empty response
    return REVIEWS.get(pid, [])
